<script setup>
import { computed, onMounted, reactive, ref } from "vue";
import Layout from "../../../layouts/main.vue";
import LoadingState from "../../../components/ui/loading-state.vue";
import { riskMatrixApi } from "../../../services/risk-matrix-api";
import { formatRiskError, showRiskError, showRiskSuccess } from "../../../components/risk-prevention/module-utils";

const loading=ref(true);const data=ref({methodologies:[],catalogs:{},permissions:[]});const selectedType=ref("risk_family");const search=ref("");const creating=ref(false);const form=reactive({catalog_type:"risk_family",code:"",name:"",description:"",color:"",sort_order:99});
const canManage=computed(()=>data.value.permissions.includes("__superadmin__")||data.value.permissions.includes("risk-matrix.manage-catalogs"));
const types=computed(()=>Object.keys(data.value.catalogs||{}));
const items=computed(()=>{const needle=search.value.toLowerCase();return (data.value.catalogs[selectedType.value]||[]).filter((item)=>!needle||`${item.code} ${item.name}`.toLowerCase().includes(needle));});
async function load(){loading.value=true;try{data.value=await riskMatrixApi.catalogs();if(!data.value.catalogs[selectedType.value])selectedType.value=types.value[0];}catch(error){showRiskError(formatRiskError(error));}finally{loading.value=false;}}
async function save(){try{const response=await riskMatrixApi.createCatalogItem({...form,methodology_id:data.value.active_methodology.id,catalog_type:selectedType.value,color:form.color||null});showRiskSuccess(response.message);creating.value=false;Object.assign(form,{code:"",name:"",description:"",color:"",sort_order:99});await load();}catch(error){showRiskError(formatRiskError(error));}}
async function toggle(item){try{const response=await riskMatrixApi.toggleCatalogItem(item.id,{active:!item.active,valid_until:item.active?new Date().toISOString().slice(0,10):null});showRiskSuccess(response.message);await load();}catch(error){showRiskError(formatRiskError(error));}}
onMounted(load);
</script>

<template><Layout><div class="catalog-hero"><div><router-link to="/risk-prevention/matrices"><i class="bx bx-left-arrow-alt"></i> Matrices IPER/MIPER</router-link><h3>Catálogos y metodología</h3><p>Configuración versionada: los cambios no alteran matrices históricas ni eliminan códigos usados.</p></div><button v-if="canManage" class="btn btn-light" @click="creating=true"><i class="bx bx-plus"></i> Nuevo elemento</button></div><LoadingState v-if="loading" message="Cargando catálogos versionados…"/><template v-else><div class="method-strip"><div><span>Metodología activa</span><strong>{{data.active_methodology.name}}</strong><small>{{data.active_methodology.code}} · versión {{data.active_methodology.version_number}}</small></div><div><span>Vigencia</span><strong>{{data.active_methodology.valid_from||'Sin fecha'}} → {{data.active_methodology.valid_until||'vigente'}}</strong></div><div><span>Fórmula</span><strong>Probabilidad × Consecuencia</strong></div><div><span>Estado</span><strong class="active-state">Activa</strong></div></div><div class="catalog-layout"><aside><div class="type-search"><i class="bx bx-search"></i><input v-model="search" placeholder="Buscar catálogo…"/></div><button v-for="type in types" :key="type" :class="{active:selectedType===type}" @click="selectedType=type"><span>{{type.replaceAll('_',' ')}}</span><strong>{{data.catalogs[type].length}}</strong></button></aside><main><header><div><span>Catálogo configurable</span><h5>{{selectedType.replaceAll('_',' ')}}</h5></div><small>{{items.length}} elementos</small></header><div class="catalog-list"><article v-for="item in items" :key="item.id" :class="{inactive:!item.active}"><span class="sort">{{item.sort_order}}</span><span v-if="item.color" class="color" :style="{background:item.color}"></span><div><strong>{{item.name}}</strong><code>{{item.code}}</code><p>{{item.description}}</p></div><div class="config"><span v-for="(value,key) in item.configuration||{}" :key="key">{{key}}: {{Array.isArray(value)?value.join(', '):value}}</span></div><button v-if="canManage" :title="item.active?'Desactivar sin eliminar':'Reactivar'" @click="toggle(item)"><i class="bx" :class="item.active?'bx-toggle-right':'bx-toggle-left'"></i></button></article><div v-if="!items.length" class="empty">Sin elementos para esta búsqueda.</div></div></main></div></template>
<div v-if="creating" class="backdrop" @click.self="creating=false"><section><header><div><span>Nuevo elemento</span><h5>{{selectedType.replaceAll('_',' ')}}</h5></div><button @click="creating=false"><i class="bx bx-x"></i></button></header><label><span>Código estable *</span><input v-model="form.code" class="form-control" placeholder="codigo_sin_espacios"/></label><label><span>Nombre *</span><input v-model="form.name" class="form-control"/></label><label><span>Descripción</span><textarea v-model="form.description" class="form-control" rows="3"></textarea></label><div class="two"><label><span>Color</span><input v-model="form.color" type="color" class="form-control form-control-color"/></label><label><span>Orden</span><input v-model.number="form.sort_order" type="number" min="0" class="form-control"/></label></div><footer><button class="btn btn-light" @click="creating=false">Cancelar</button><button class="btn btn-primary" @click="save">Crear en metodología activa</button></footer></section></div></Layout></template>

<style scoped>
.catalog-hero{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;padding:1.1rem 1.25rem;border-radius:13px;background:linear-gradient(125deg,#1c3249,#315a69);color:#fff}.catalog-hero a{color:#cee1e6;font-size:.6rem}.catalog-hero h3{margin:.15rem 0}.catalog-hero p{margin:0;color:#d4e4e8;font-size:.68rem}.catalog-hero .btn{display:inline-flex;align-items:center;gap:.3rem}.method-strip{display:grid;grid-template-columns:2fr repeat(3,1fr);margin-top:.7rem;border:1px solid #e0e7ee;border-radius:10px;background:#fff}.method-strip>div{padding:.7rem;border-right:1px solid #e0e7ee}.method-strip span,.method-strip strong,.method-strip small{display:block}.method-strip span,.method-strip small{color:#667085;font-size:.56rem}.method-strip strong{font-size:.69rem}.active-state{color:#15803d}.catalog-layout{display:grid;grid-template-columns:240px 1fr;gap:.7rem;margin-top:.7rem}.catalog-layout aside,.catalog-layout main{overflow:hidden;border:1px solid #e0e7ee;border-radius:10px;background:#fff}.type-search{display:flex;align-items:center;gap:.3rem;margin:.55rem;padding:.35rem .45rem;border:1px solid #d9e1e9;border-radius:6px}.type-search input{width:100%;border:0;outline:0;font-size:.65rem}.catalog-layout aside>button{display:flex;justify-content:space-between;width:100%;padding:.48rem .65rem;border:0;border-top:1px solid #edf0f3;background:#fff;color:#536174;font-size:.61rem;text-align:left;text-transform:capitalize}.catalog-layout aside>button.active{border-left:3px solid #16806f;background:#eef7f5;color:#176b76;font-weight:700}.catalog-layout aside>button strong{padding:.1rem .25rem;border-radius:99px;background:#eef2f6}.catalog-layout main>header{display:flex;justify-content:space-between;padding:.7rem .8rem;border-bottom:1px solid #edf0f3}.catalog-layout main header span,.catalog-layout main header small{color:#667085;font-size:.56rem}.catalog-layout main h5{margin:.1rem 0;text-transform:capitalize}.catalog-list article{display:grid;grid-template-columns:30px 10px minmax(200px,1fr) 1fr 36px;align-items:center;gap:.55rem;padding:.6rem .7rem;border-bottom:1px solid #edf0f3}.catalog-list article.inactive{opacity:.55;background:#f8fafc}.sort{display:grid;place-items:center;width:26px;height:26px;border-radius:6px;background:#f2f4f7;color:#667085;font-size:.56rem}.color{width:9px;height:34px;border-radius:99px}.catalog-list strong,.catalog-list code,.catalog-list p{display:block}.catalog-list strong{font-size:.68rem}.catalog-list code{color:#176b76;font-size:.55rem}.catalog-list p{margin:.1rem 0 0;color:#667085;font-size:.57rem}.config{display:flex;flex-wrap:wrap;gap:.25rem}.config span{padding:.18rem .28rem;border-radius:4px;background:#f2f4f7;color:#667085;font-size:.5rem}.catalog-list article>button{border:0;background:none;color:#16806f;font-size:1.4rem}.empty{padding:2rem;color:#667085;text-align:center}.backdrop{position:fixed;z-index:1100;inset:0;display:grid;place-items:center;padding:1rem;background:rgba(16,24,40,.5)}.backdrop>section{width:min(520px,100%);padding:1rem;border-radius:12px;background:#fff}.backdrop header{display:flex;justify-content:space-between}.backdrop header span,.backdrop label span{display:block;color:#667085;font-size:.57rem}.backdrop h5{margin:.1rem 0}.backdrop header button{border:0;background:none;font-size:1.2rem}.backdrop label{display:block;margin-top:.6rem}.two{display:grid;grid-template-columns:1fr 1fr;gap:.5rem}.backdrop footer{display:flex;justify-content:flex-end;gap:.4rem;margin-top:.8rem}@media(max-width:800px){.method-strip{grid-template-columns:1fr 1fr}.catalog-layout{grid-template-columns:1fr}.catalog-layout aside{display:flex;overflow:auto}.type-search{min-width:180px}.catalog-layout aside>button{min-width:150px}.catalog-list article{grid-template-columns:30px 10px 1fr 36px}.config{display:none}}
</style>
